// Universal seed build: brands/<id>/ (data + layout) -> static site. The core never names a brand.
//
// A brand layout (brands/<id>/layout/index.mjs) exports:
//   header(ctx), footer(ctx)                          -> HTML strings
//   pages: { home, collection, product, story, [cart, orders, policies, thanks], [extra: {slug: fn}] }
//   (privacy/terms/returns/shipping always come from core/policies.mjs so every shop says the same true things)
//          each (ctx[, product]) -> { title?, description?, body, image? } (or a body string)
// and ships layout/styles.css. ctx = { brand, products, shown, archive, drops, now, kit, page, root }.
// Core adds: <head> (SEO/OG/JSON-LD/noindex), tokens -> CSS custom properties, base.css, seed.js
// (cart + menu + forms), catalog.js (public product data), robots.txt and the shared pages.
import { readFileSync, writeFileSync, mkdirSync, cpSync, existsSync, readdirSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { readBrandDir, validateCatalog, productView, publicCatalog } from './catalog.mjs';
import { createKit, esc } from './kit.mjs';
import { radiusErrors, templateRadiusErrors } from './style-rules.mjs';
import { POLICY_PAGES, POLICY_BODIES, policyFields, policyGaps, legalNav } from './policies.mjs';
import { basePath, shopUrl } from './site.mjs';

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CORE = dirname(fileURLToPath(import.meta.url));

export const brandIds = (root = ROOT) => readdirSync(join(root, 'brands'), { withFileTypes: true })
  .filter((d) => d.isDirectory() && !d.name.startsWith('_') && existsSync(join(root, 'brands', d.name, 'brand.json')))
  .map((d) => d.name).sort();

export function loadBrand(id, root = ROOT, opts = {}) {
  const b = readBrandDir(join(root, 'brands', id), opts);
  return { ...b, products: b.catalog };
}

/** seed.js = core/cart.mjs (exports stripped) + core/client/seed.js, in one IIFE: a classic script, file:// safe. */
export function clientBundle() {
  const cart = readFileSync(join(CORE, 'cart.mjs'), 'utf8').replace(/^export\s+/gm, '');
  const ui = readFileSync(join(CORE, 'client', 'seed.js'), 'utf8');
  return `/* universal storefront seed: cart + ui (generated by core/build.mjs) */\n(function () {\n'use strict';\n${cart}\n${ui}\n})();\n`;
}

function tokensCss(brand, products) {
  const t = brand.tokens ?? {};
  const vars = [
    ...Object.entries(t.colors ?? {}).map(([k, v]) => `--c-${k}:${v}`),
    ...Object.entries(t.fonts ?? {}).map(([k, v]) => `--f-${k}:${v}`),
    ...Object.entries(t.vars ?? {}).map(([k, v]) => `--${k}:${v}`),
  ];
  const sw = new Map();
  for (const p of products) for (const c of p.colors ?? []) sw.set(c.id, c.hex);
  return `:root{${vars.join(';')}}\n${[...sw].map(([id, hex]) => `.sw-${id}{background:${hex}}`).join('\n')}\n`;
}

/** Absolute URL of a page-relative or root-absolute asset path ("../assets/x.jpg", "/shop/assets/x.jpg"). */
const absUrl = (brand, p) => {
  const base = basePath(brand);
  const rel = String(p).replace(/^(\.\.\/)+/, '');
  return base && rel.startsWith(`${base}/`) ? `https://${brand.domain}${rel}` : `${shopUrl(brand)}/${rel.replace(/^\//, '')}`;
};

function head({ brand, title, description, path, image, preview, jsonld, root }) {
  // A shop under a path has its home at https://<domain>/shop (no slash: a main site may run trailingSlash:false).
  const url = path === 'index.html' ? (basePath(brand) ? shopUrl(brand) : `${shopUrl(brand)}/`) : `${shopUrl(brand)}/${path}`;
  const og = image ? absUrl(brand, image) : null;
  const fonts = brand.tokens?.fontsHref
    ? `<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="${esc(brand.tokens.fontsHref)}">` : '';
  return `<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title><meta name="description" content="${esc(description)}">
${preview ? '<meta name="robots" content="noindex, nofollow">' : ''}<link rel="canonical" href="${esc(url)}">
<meta property="og:type" content="website"><meta property="og:site_name" content="${esc(brand.name)}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${esc(url)}">
${og ? `<meta property="og:image" content="${esc(og)}"><meta name="twitter:card" content="summary_large_image">` : '<meta name="twitter:card" content="summary">'}
<meta name="theme-color" content="${esc(brand.tokens?.colors?.bg ?? '#ffffff')}">
${brand.favicon ? `<link rel="icon" href="${root}${esc(brand.favicon)}">` : ''}
${fonts}<link rel="stylesheet" href="${root}base.css"><link rel="stylesheet" href="${root}styles.css">
${jsonld ? `<script type="application/ld+json">${JSON.stringify(jsonld).replace(/</g, '\\u003c')}</script>` : ''}`;
}

/** A footer may carry this marker (inside its own wrap) to place the main-site and policy links; else they go
 *  right before </footer>. */
export const LEGAL_SLOT = '<!--seed-legal-->';

/** brand.json `main_site` {label, url}: the only link between a shop and its main site, rendered by the core in
 *  the footer (Principal 2026-10-14: "it shold only be footer link to get betweeen main site and shop for now").
 *  Shops that ARE their brand's main site leave it out. Headers and navs never carry it (a test checks). */
function withMainSite(footer, { brand }) {
  const m = brand.main_site;
  if (!m?.url) return footer;
  const link = `<p class="seed-mainsite"><a href="${esc(m.url)}">${esc(m.label ?? m.url)}</a></p>`;
  const i = footer.includes(LEGAL_SLOT) ? footer.indexOf(LEGAL_SLOT) : footer.lastIndexOf('</footer>');
  return i < 0 ? footer + link : `${footer.slice(0, i)}${link}${footer.slice(i)}`;
}

/** Every footer carries the shared policy links (Privacy, Terms, Returns and pre-orders, Shipping, Contact),
 *  rendered by the core so no shop can ship without them (a test checks every page). */
function withLegal(footer, { brand, kit }) {
  const nav = legalNav(brand, (id) => kit.href[id]());
  const i = footer.includes(LEGAL_SLOT) ? footer.indexOf(LEGAL_SLOT) : footer.lastIndexOf('</footer>');
  return i < 0 ? footer + nav : `${footer.slice(0, i)}${nav}${footer.slice(i)}`;
}

/** Small corners: every stylesheet and template a brand ships passes core/style-rules.mjs, or the build fails. */
export function styleErrors(dir) {
  return [
    ...radiusErrors(readFileSync(join(CORE, 'base.css'), 'utf8'), 'core/base.css'),
    ...radiusErrors(readFileSync(join(dir, 'layout', 'styles.css'), 'utf8'), `${dir.split('/').slice(-1)[0]}/layout/styles.css`),
    ...templateRadiusErrors(readFileSync(join(dir, 'layout', 'index.mjs'), 'utf8'), `${dir.split('/').slice(-1)[0]}/layout/index.mjs`),
  ];
}

function shell(L, ctx, page, out) {
  const r = typeof out === 'string' ? { body: out } : out;
  const { brand, kit, root } = ctx;
  const title = r.title ?? brand.name;
  const description = r.description ?? brand.description ?? brand.tagline ?? brand.name;
  return `<!doctype html>
<html lang="en" data-root="${root}" data-page="${page.id}"><head>
${head({ brand, title, description, path: page.path, image: r.image, preview: brand.mode !== 'live', jsonld: r.jsonld, root })}
<script src="${root}catalog.js" defer></script><script src="${root}seed.js" defer></script>
</head><body class="page-${page.id}">
${kit.skipLink()}${kit.previewBanner()}
${L.header(ctx)}
<main id="main" tabindex="-1">${r.body}</main>
${withLegal(withMainSite(L.footer(ctx), ctx), ctx)}
</body></html>
`;
}

/** Build one brand into outDir. */
export async function buildBrand(id, outDir, { now = new Date(), root = ROOT, env = process.env, mode = null } = {}) {
  if (id.startsWith('_')) throw new Error(`"${id}" is not a shop (folders starting with _ are never built)`);
  const { dir, brand, catalog, drops, manifest } = readBrandDir(join(root, 'brands', id), { now });
  if (mode) brand.mode = mode; // --live: build as the live shop without editing brand.json (launch checks, staging)
  validateCatalog(catalog, drops, brand.palette ?? null, brand.print_rules ?? {});
  const se = styleErrors(dir);
  if (se.length) throw new Error(`style rules:\n  ${se.join('\n  ')}`);
  const L = await import(pathToFileURL(join(dir, 'layout', 'index.mjs')).href);
  const listed = catalog.filter((p) => p.listed !== false);
  const checkout = brand.mode === 'live' && env.CHECKOUT_ENABLED === 'true';
  // Release-managed items (catalog `release`) read their labels from brand.json and pre-order only while checkout is open.
  const viewOpts = { checkout, release: brand.release_states ?? {} };
  const views = Object.fromEntries(listed.map((p) => [p.id, productView(p, drops, now, viewOpts)]));
  // Archive pieces live in their own section; everything else is the current shop.
  const shown = listed.filter((p) => views[p.id].status !== 'archive');
  const archive = listed.filter((p) => views[p.id].status === 'archive');
  // Launch gate: a live shop may not publish policy pages with unconfirmed facts (entity, inbox, address, law...).
  const gaps = brand.mode === 'live' ? policyGaps(brand) : [];
  if (gaps.length) throw new Error(`policies: confirm before going live:\n  ${gaps.join('\n  ')}`);

  rmSync(outDir, { recursive: true, force: true });
  // base_path (e.g. /shop): the shop is served under its main site. Files go to outDir/shop/ and every link is
  // root-absolute ("/shop/..."), so /shop, /shop/ and the main-site rewrite all resolve the same assets.
  const base = basePath(brand);
  const siteDir = outDir;
  outDir = base ? join(outDir, ...base.split('/').filter(Boolean)) : outDir;
  const R = (rel) => (base ? `${base}/` : rel);
  mkdirSync(join(outDir, 'products'), { recursive: true });
  if (existsSync(join(dir, 'assets'))) cpSync(join(dir, 'assets'), join(outDir, 'assets'), { recursive: true, filter: (s) => !s.endsWith('manifest.json') });
  writeFileSync(join(outDir, 'base.css'), readFileSync(join(CORE, 'base.css'), 'utf8'));
  writeFileSync(join(outDir, 'styles.css'), tokensCss(brand, listed) + readFileSync(join(dir, 'layout', 'styles.css'), 'utf8'));
  writeFileSync(join(outDir, 'seed.js'), clientBundle());

  const pages = [];
  const make = (pid, path, rel, fn) => {
    const rootRel = R(rel);
    const kit = createKit({ brand, manifest, root: rootRel, views });
    const ctx = { brand, products: listed, shown, archive, drops, now, kit, root: rootRel, page: pid };
    const html = shell(L, ctx, { id: pid, path }, fn(ctx));
    writeFileSync(join(outDir, path), html);
    pages.push(path);
  };
  const P = L.pages ?? {};
  const want = brand.pages ?? ['home', 'collection', 'story', 'cart', 'orders', 'policies', 'thanks', 'product'];
  if (want.includes('home')) make('home', 'index.html', '', (c) => P.home(c));
  if (want.includes('collection')) make('collection', 'shop.html', '', (c) => P.collection(c));
  if (want.includes('story') && P.story) make('story', 'story.html', '', (c) => P.story(c));
  // Extra brand pages: pages.extra = {'<slug>': (ctx) => page} -> <slug>.html (page id = slug).
  for (const [slug, fn] of Object.entries(P.extra ?? {})) {
    if (!/^[a-z0-9-]+$/.test(slug) || ['index', 'shop', 'story', 'cart', 'orders', 'policies', 'thanks', '404', ...POLICY_PAGES.map((x) => x.id)].includes(slug)) throw new Error(`bad extra page "${slug}"`);
    make(slug, `${slug}.html`, '', (c) => fn(c));
  }
  if (want.includes('cart')) make('cart', 'cart.html', '', (c) => (P.cart ? P.cart(c) : { title: `Bag | ${brand.name}`, body: c.kit.cartBody() }));
  if (want.includes('orders')) make('orders', 'orders.html', '', (c) => (P.orders ? P.orders(c) : { title: `Order lookup | ${brand.name}`, body: c.kit.ordersBody() }));
  if (want.includes('policies')) {
    make('policies', 'policies.html', '', (c) => (P.policies ? P.policies(c) : { title: `Shipping, returns and policies | ${brand.name}`, body: c.kit.policiesBody() }));
    // Privacy, Terms, Returns and pre-orders, Shipping: one shared template, per-brand fields (core/policies.mjs).
    for (const pg of POLICY_PAGES) {
      make(pg.id, pg.path, '', (c) => ({ title: `${pg.label} | ${brand.name}`, description: `${pg.label} for ${brand.name}.`,
        body: POLICY_BODIES[pg.id](policyFields(brand), (id) => c.kit.href[id]()) }));
    }
  }
  if (want.includes('thanks')) make('thanks', 'thanks.html', '', (c) => (P.thanks ? P.thanks(c) : { title: `Thank you | ${brand.name}`, body: c.kit.thanksBody() }));
  if (want.includes('product')) {
    for (const p of listed) {
      make('product', `products/${p.id}.html`, '../', (c) => {
        const r = P.product(c, p);
        const img = p.images?.[0] ? c.kit.imgData(p.images[0]).src : undefined;
        const v = views[p.id];
        const jsonld = { '@context': 'https://schema.org', '@type': 'Product', name: p.name, brand: { '@type': 'Brand', name: brand.name }, description: p.summary ?? p.description ?? '',
          ...(img ? { image: absUrl(brand, img) } : {}),
          ...(v.price_cents !== null && v.canAdd ? { offers: { '@type': 'Offer', price: (v.price_cents / 100).toFixed(2), priceCurrency: 'USD', availability: v.preorder ? 'https://schema.org/PreOrder' : 'https://schema.org/InStock' } } : {}) };
        return { title: `${p.name} | ${brand.name}`, description: p.summary ?? p.description, image: img, jsonld, ...(typeof r === 'string' ? { body: r } : r) };
      });
    }
  }
  const kit0 = createKit({ brand, manifest, root: '', views }); // page-relative: seed.js prefixes data-root
  const data = {
    brand: { id: brand.id, name: brand.name }, preview: brand.mode !== 'live', checkout, api: `${base}/api`,
    copy: { checkoutOff: brand.copy?.checkoutOff ?? 'Checkout opens when the shop does.', lookupOff: 'Order lookup opens when the shop does.', notifyOff: 'Sign-ups open when the shop does. Nothing was saved.' },
    products: publicCatalog(listed, drops, now, {
      imageFor: (p) => (p.images?.[0] ? kit0.imgData(p.images[0]).src.replace(/-\d+\.(jpg|webp)$/, (m, ext) => { const w = manifest[p.images[0].file]?.widths?.[0]; return w ? `-${w}.${ext}` : m; }) : ''),
      urlFor: (p) => `products/${p.id}.html`, viewOpts,
    }),
  };
  writeFileSync(join(outDir, 'catalog.js'), `window.SEED = ${JSON.stringify(data)};\n`);
  writeFileSync(join(outDir, 'robots.txt'), brand.mode === 'live' ? 'User-agent: *\nAllow: /\n' : 'User-agent: *\nDisallow: /\n');
  if (existsSync(join(outDir, 'index.html'))) cpSync(join(outDir, 'index.html'), join(outDir, '404.html'));
  if (base) { // the shop project's own origin: its robots + 404 (links are root-absolute, so the 404 renders anywhere)
    writeFileSync(join(siteDir, 'robots.txt'), readFileSync(join(outDir, 'robots.txt'), 'utf8'));
    cpSync(join(outDir, '404.html'), join(siteDir, '404.html'));
  }
  return { brand: id, pages: pages.length, products: listed.length, out: outDir };
}

/** Holding page for a brand's public domain before the shop launches. Indexable, no forms, no prices, no scripts.
 *  Driven by brand.json `holding`: {lede, sub, shots: [asset file names under brands/<id>/<dir>]}. */
export function buildHolding(id, outDir, { root = ROOT } = {}) {
  const { dir, brand } = readBrandDir(join(root, 'brands', id), { merge: false });
  const h = brand.holding ?? {};
  rmSync(outDir, { recursive: true, force: true });
  mkdirSync(join(outDir, 'photos'), { recursive: true });
  const shots = (h.shots ?? []).filter((s) => existsSync(join(dir, s)));
  shots.forEach((s, i) => cpSync(join(dir, s), join(outDir, 'photos', `${i + 1}.jpg`)));
  const seal = h.seal && existsSync(join(dir, h.seal)) ? h.seal : null;
  if (seal) cpSync(join(dir, seal), join(outDir, 'seal.png'));
  const c = brand.tokens?.colors ?? {};
  const f = brand.tokens?.fonts ?? {};
  writeFileSync(join(outDir, 'styles.css'), `*{box-sizing:border-box}body{margin:0;background:${c.bg};color:${c.fg};font:16px/1.6 ${f.body};text-align:center}
main{max-width:1040px;margin:0 auto;padding:56px 20px 40px}img.seal{width:96px;height:96px;margin:0 auto 18px;display:block}
h1{font:500 clamp(42px,8vw,84px)/1 ${f.display};letter-spacing:.04em;margin:0}.bar{width:64px;height:4px;background:${c.accent};margin:22px auto}
.end{font-size:13px;color:${c.muted};letter-spacing:.08em;text-transform:uppercase}.lede{font:400 24px/1.4 ${f.display};margin:28px auto 8px;max-width:640px}
.sub{color:${c.muted};margin:0 auto 40px;max-width:560px}.shots{display:grid;grid-template-columns:repeat(${shots.length || 1},minmax(0,1fr));gap:18px}
.shots img{width:100%;height:auto;display:block}footer{margin-top:48px;font-size:13px;color:${c.muted}}
@media (max-width:640px){.shots{grid-template-columns:minmax(0,1fr)}}`);
  const og = shots.length ? `https://${brand.domain}/photos/1.jpg` : null;
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(brand.name)}: the first drop is coming</title>
<meta name="description" content="${esc(brand.name)}, ${esc(brand.endorsement ?? '')}. ${esc(h.sub ?? '')} The first drop is coming soon.">
<meta property="og:title" content="${esc(brand.name)}"><meta property="og:description" content="The first drop is coming.">
<link rel="canonical" href="https://${esc(brand.domain)}/"><meta property="og:type" content="website"><meta property="og:url" content="https://${esc(brand.domain)}/">
${og ? `<meta property="og:image" content="${og}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="${og}">` : ''}
<meta name="twitter:title" content="${esc(brand.name)}"><meta name="theme-color" content="${esc(c.bg ?? '#ffffff')}">
<link rel="stylesheet" href="styles.css">${seal ? '<link rel="icon" href="seal.png">' : ''}</head><body><main>
${seal ? `<img class="seal" src="seal.png" alt="${esc(brand.name)} seal" width="96" height="96">` : ''}
<h1>${esc(brand.name)}</h1><div class="end">${esc(brand.endorsement ?? '')}</div><div class="bar"></div>
<p class="lede">${esc(h.lede ?? brand.tagline ?? '')}. The first drop is coming.</p>
<p class="sub">${esc(h.sub ?? '')}</p>
<div class="shots">${shots.map((_, i) => `<img src="photos/${i + 1}.jpg" alt="${esc(brand.name)} piece" loading="lazy">`).join('')}</div>
<footer>© ${new Date().getUTCFullYear()} ${esc(brand.name)}</footer></main></body></html>`;
  writeFileSync(join(outDir, 'index.html'), html);
  writeFileSync(join(outDir, '404.html'), html);
  writeFileSync(join(outDir, 'robots.txt'), 'User-agent: *\nAllow: /\n');
  writeFileSync(join(outDir, 'vercel.json'), JSON.stringify({ cleanUrls: true, headers: [{ source: '/(.*)', headers: [
    { key: 'X-Content-Type-Options', value: 'nosniff' }, { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
    { key: 'X-Frame-Options', value: 'DENY' }, { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=()' },
    { key: 'Content-Security-Policy', value: "default-src 'self'; img-src 'self' data:; style-src 'self'; script-src 'none'; frame-ancestors 'none'; base-uri 'self'; form-action 'none'" },
  ] }] }, null, 2));
  return { brand: id, holding: true, out: outDir, shots: shots.length };
}
